/* TodoMVC Vanilla JS
 *
 * Spec: assets/app-spec.md
 * Base markup: index.html
 * Storage key: todos-vanillajs
 */
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // ── Helpers ───────────────────────────────────────────────────────────

  function qs(sel, ctx) { return (ctx || document).querySelector(sel); }

  function qsa(sel, ctx) { return (ctx || document).querySelectorAll(sel); }

  function pluralize(count) { return count === 1 ? 'item' : 'items'; }

  function getTodos() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
    catch (_) { return []; }
  }

  function setTodos(todos) {
    // Strip transient UI state before persisting
    var clean = todos.map(function (t) {
      return { id: t.id, title: t.title, completed: t.completed };
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify(clean));
  }

  function genId() {
    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6);
  }

  // ── App state ──────────────────────────────────────────────────────────

  var todos = [];
  var currentFilter = 'all';

  // ── DOM refs (set after DOM ready) ─────────────────────────────────────

  var newTodoInput;
  var todoList;
  var mainSection;
  var footerSection;
  var todoCount;
  var clearCompleted;
  var toggleAll;
  var filterLinks;

  // ── Render ─────────────────────────────────────────────────────────────

  function getFilteredTodos() {
    if (currentFilter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (currentFilter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  function render() {
    todos = getTodos();
    var filtered = getFilteredTodos();
    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      // ── Toggle ──────────────────────────────────────────────────
      li.querySelector('.toggle').addEventListener('click', function () {
        todo.completed = this.checked;
        todo.editing = false;
        setTodos(todos);
        render();
      });

      // ── Destroy ─────────────────────────────────────────────────
      li.querySelector('.destroy').addEventListener('click', function () {
        todos = todos.filter(function (t) { return t !== todo; });
        setTodos(todos);
        render();
      });

      // ── Label dblclick → edit ───────────────────────────────────
      li.querySelector('label').addEventListener('dblclick', function () {
        todo.editing = true;
        render();
        var editInput = li.querySelector('.edit');
        editInput.focus();
        editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
      });

      // ── Edit input ──────────────────────────────────────────────
      var editInput = li.querySelector('.edit');
      editInput.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          e.preventDefault();
          commitEdit(li, todo);
        } else if (e.keyCode === ESCAPE_KEY) {
          todo.editing = false;
          setTodos(todos);
          render();
        }
      });
      editInput.addEventListener('blur', function () {
        commitEdit(li, todo);
      });

      if (todo.editing) li.classList.add('editing');

      todoList.appendChild(li);
    });

    // Main / footer visibility
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footerSection.style.display = 'none';
    } else {
      mainSection.style.display = 'block';
      footerSection.style.display = 'block';
    }

    // Toggle all
    var allDone = todos.length > 0 && getCompletedCount() === todos.length;
    toggleAll.checked = allDone;

    // Clear completed
    var hasCompleted = getCompletedCount() > 0;
    clearCompleted.style.display = hasCompleted ? 'block' : 'none';

    // Todo count
    var active = getActiveCount();
    todoCount.innerHTML = '<strong>' + active + '</strong> ' + pluralize(active) + ' left';

    // Filter links
    filterLinks.forEach(function (a) {
      a.classList.remove('selected');
      var href = a.getAttribute('href');
      if ((href === '#/' && currentFilter === 'all') ||
          (href === '#/active' && currentFilter === 'active') ||
          (href === '#/completed' && currentFilter === 'completed')) {
        a.classList.add('selected');
      }
    });
  }

  function commitEdit(li, todo) {
    var editInput = li.querySelector('.edit');
    var val = editInput.value.trim();
    if (val) {
      todo.title = val;
      todo.editing = false;
    } else {
      todos = todos.filter(function (t) { return t !== todo; });
    }
    setTodos(todos);
    render();
  }

  // ── New todo ───────────────────────────────────────────────────────────

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({
      id: genId(),
      title: title,
      completed: false,
      editing: false,
    });
    setTodos(todos);
    render();
  }

  // ── Toggle all ─────────────────────────────────────────────────────────

  function toggleAllTodos() {
    var allDone = getCompletedCount() === todos.length;
    todos.forEach(function (t) { t.completed = !allDone; });
    setTodos(todos);
    render();
  }

  // ── Clear completed ────────────────────────────────────────────────────

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    setTodos(todos);
    render();
  }

  // ── Routing ────────────────────────────────────────────────────────────

  function route() {
    var hash = window.location.hash || '#/';
    if (hash === '#/' || hash === '' || hash === '#') {
      currentFilter = 'all';
    } else if (hash === '#/active') {
      currentFilter = 'active';
    } else if (hash === '#/completed') {
      currentFilter = 'completed';
    } else {
      currentFilter = 'all';
    }
    render();
  }

  // ── Init ───────────────────────────────────────────────────────────────

  function init() {
    newTodoInput = qs('.new-todo');
    todoList = qs('.todo-list');
    mainSection = qs('.main');
    footerSection = qs('.footer');
    todoCount = qs('.todo-count');
    clearCompleted = qs('.clear-completed');
    toggleAll = qs('.toggle-all');
    filterLinks = qsa('.filters a');

    todos = getTodos();

    // New todo: Enter to add
    newTodoInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        e.preventDefault();
        addTodo(newTodoInput.value);
        newTodoInput.value = '';
      }
    });

    // Toggle all
    toggleAll.addEventListener('click', toggleAllTodos);

    // Clear completed
    clearCompleted.addEventListener('click', clearCompletedTodos);

    // Routing
    window.addEventListener('hashchange', route);

    render();
    newTodoInput.focus();
  }

  // Wait for DOM ready (for when loaded via <script> or harness eval)
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

